// Jellyseerr sends the payload as top-level JSON keys (no wrapper object)
const body = $input.first().json;

// Notification types: MEDIA_PENDING, MEDIA_APPROVED, MEDIA_DECLINED,
//                     MEDIA_AVAILABLE, MEDIA_FAILED, TEST_NOTIFICATION
const notifType = body.notification_type || '';
const subject   = body.subject || 'Unknown Title';
const message   = body.message || subject;
const mediaType = (body.media || {}).media_type || 'movie';
const image     = body.image || '';

// Extract title and year from subject like "City of God (2002)"
const match = subject.match(/^(.+?)\s*\((\d{4})\)\s*$/);
const title = match ? match[1] : subject;
const year  = match ? parseInt(match[2]) : 0;

const eventMap = {
  MEDIA_PENDING:      'Requested',
  MEDIA_APPROVED:     'Approved',
  MEDIA_DECLINED:     'Declined',
  MEDIA_AVAILABLE:    'Now Available',
  MEDIA_FAILED:       'Download Failed',
  TEST_NOTIFICATION:  'Test',
};
const event = eventMap[notifType] || notifType;

// Include Watch Now button only for downloading or available media
const showWatchNow = ['MEDIA_AVAILABLE'].includes(notifType);
const watchNowAction = showWatchNow
  ? `http, Watch Now, http://media-watcher:8888/prioritize, POST, body={"title":"${title}","year":${year}}`
  : '';

return [{ json: { subject, title, year, mediaType, event, message, image, notifType, showWatchNow, watchNowAction } }];
